-- Base de datos unificada de estudios técnicos de flotas
-- MySQL 8.0+. Persistencia y trazabilidad; la lógica de decisión pertenece a la aplicación.
CREATE DATABASE IF NOT EXISTS technical_studies CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE technical_studies;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS audit_event;
DROP TABLE IF EXISTS study_event;
DROP TABLE IF EXISTS attachment_link;
DROP TABLE IF EXISTS assessment_revision_business_rule;
DROP TABLE IF EXISTS assessment_revision_source_document;
DROP TABLE IF EXISTS canbus_assessment_parameter;
DROP TABLE IF EXISTS canbus_assessment_document;
DROP TABLE IF EXISTS canbus_assessment_detail;
DROP TABLE IF EXISTS tachograph_assessment_decision;
DROP TABLE IF EXISTS tachograph_assessment_detail;
DROP TABLE IF EXISTS assessment_revision;
DROP TABLE IF EXISTS assessment;
DROP TABLE IF EXISTS study_vehicle;
DROP TABLE IF EXISTS technical_study;
DROP TABLE IF EXISTS vehicle;
DROP TABLE IF EXISTS client;
DROP TABLE IF EXISTS canbus_document_parameter;
DROP TABLE IF EXISTS canbus_document_extraction_attempt;
DROP TABLE IF EXISTS canbus_document_analysis;
DROP TABLE IF EXISTS canbus_parameter;
DROP TABLE IF EXISTS app_user;
DROP TABLE IF EXISTS assessment_type;
DROP TABLE IF EXISTS tachograph_decision_business_rule;
DROP TABLE IF EXISTS tachograph_decision_source_document;
DROP TABLE IF EXISTS tachograph_compatibility_decision;
DROP TABLE IF EXISTS tachograph_document_occurrence;
DROP TABLE IF EXISTS tachograph_identifier;
DROP TABLE IF EXISTS tachograph_identifier_type;
DROP TABLE IF EXISTS tachograph_model;
DROP TABLE IF EXISTS tachograph_manufacturer;
DROP TABLE IF EXISTS canbus_document_issue;
DROP TABLE IF EXISTS canbus_document_part;
DROP TABLE IF EXISTS canbus_document;
DROP TABLE IF EXISTS canbus_manufacturer;
DROP TABLE IF EXISTS canbus_import_batch;
DROP TABLE IF EXISTS business_rule;
DROP TABLE IF EXISTS source_document;
DROP TABLE IF EXISTS file_asset;

SET FOREIGN_KEY_CHECKS = 1;

CREATE TABLE file_asset (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  original_filename VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs NOT NULL,
  storage_key VARCHAR(500) NULL,
  mime_type VARCHAR(120) NULL,
  size_bytes BIGINT UNSIGNED NULL,
  sha256 CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id), UNIQUE KEY uq_file_asset_sha256 (sha256)
) ENGINE=InnoDB;

CREATE TABLE source_document (
  id SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
  file_asset_id BIGINT UNSIGNED NULL,
  code VARCHAR(50) NOT NULL,
  domain VARCHAR(30) NOT NULL,
  source_type VARCHAR(40) NOT NULL,
  title VARCHAR(255) NOT NULL,
  document_date DATE NULL,
  notes TEXT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id), UNIQUE KEY uq_source_document_code (code),
  CONSTRAINT fk_source_document_file FOREIGN KEY (file_asset_id) REFERENCES file_asset (id)
) ENGINE=InnoDB;

CREATE TABLE business_rule (
  id SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
  code VARCHAR(80) NOT NULL,
  version VARCHAR(20) NOT NULL,
  domain VARCHAR(30) NOT NULL,
  description TEXT NOT NULL,
  effective_from DATE NULL,
  effective_to DATE NULL,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id), UNIQUE KEY uq_business_rule_version (code, version), KEY ix_business_rule_domain (domain, is_active)
) ENGINE=InnoDB;

CREATE TABLE canbus_import_batch (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, source_filename VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs NOT NULL,
  source_sha256 CHAR(64) NOT NULL, source_row_count INT UNSIGNED NOT NULL, unique_document_count INT UNSIGNED NOT NULL,
  duplicate_row_count INT UNSIGNED NOT NULL, parser_version VARCHAR(30) NOT NULL, imported_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
) ENGINE=InnoDB;
CREATE TABLE canbus_manufacturer (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, name VARCHAR(120) NOT NULL, normalized_key VARCHAR(120) NOT NULL,
  PRIMARY KEY (id), UNIQUE KEY uq_canbus_manufacturer_normalized_key (normalized_key)
) ENGINE=InnoDB;
CREATE TABLE canbus_document (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, import_batch_id BIGINT UNSIGNED NOT NULL, manufacturer_id BIGINT UNSIGNED NOT NULL,
  original_filename VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs NOT NULL,
  vehicle_descriptor_original VARCHAR(255) NOT NULL, vehicle_descriptor_normalized VARCHAR(255) NOT NULL,
  start_year SMALLINT UNSIGNED NULL, language_code VARCHAR(10) NULL, file_extension VARCHAR(20) NULL,
  parse_status VARCHAR(30) NOT NULL, occurrence_count SMALLINT UNSIGNED NOT NULL DEFAULT 1, source_line_first INT UNSIGNED NOT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id), UNIQUE KEY uq_canbus_document_original_filename (original_filename),
  KEY ix_canbus_document_lookup (manufacturer_id, vehicle_descriptor_normalized, start_year), KEY ix_canbus_document_status (parse_status),
  CONSTRAINT fk_canbus_document_batch FOREIGN KEY (import_batch_id) REFERENCES canbus_import_batch (id),
  CONSTRAINT fk_canbus_document_manufacturer FOREIGN KEY (manufacturer_id) REFERENCES canbus_manufacturer (id)
) ENGINE=InnoDB;
CREATE TABLE canbus_document_part (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, document_id BIGINT UNSIGNED NOT NULL, token_zone VARCHAR(20) NOT NULL,
  token_position SMALLINT UNSIGNED NOT NULL, original_value VARCHAR(150) NOT NULL, normalized_value VARCHAR(150) NOT NULL,
  semantic_type VARCHAR(40) NULL, canonical_value VARCHAR(150) NULL,
  PRIMARY KEY (id), UNIQUE KEY uq_canbus_part_position (document_id, token_zone, token_position),
  KEY ix_canbus_part_semantic (semantic_type, normalized_value),
  CONSTRAINT fk_canbus_part_document FOREIGN KEY (document_id) REFERENCES canbus_document (id) ON DELETE CASCADE
) ENGINE=InnoDB;
CREATE TABLE canbus_document_issue (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, document_id BIGINT UNSIGNED NOT NULL, issue_code VARCHAR(50) NOT NULL, issue_message VARCHAR(255) NOT NULL,
  PRIMARY KEY (id), KEY ix_canbus_issue_document (document_id), KEY ix_canbus_issue_code (issue_code),
  CONSTRAINT fk_canbus_issue_document FOREIGN KEY (document_id) REFERENCES canbus_document (id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE tachograph_manufacturer (
  id SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT, code VARCHAR(32) NOT NULL, name VARCHAR(100) NOT NULL,
  PRIMARY KEY (id), UNIQUE KEY uq_tachograph_manufacturer_code (code)
) ENGINE=InnoDB;
CREATE TABLE tachograph_model (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, manufacturer_id SMALLINT UNSIGNED NOT NULL,
  device_type VARCHAR(20) NOT NULL, commercial_version VARCHAR(40) NULL, generation VARCHAR(40) NULL,
  PRIMARY KEY (id), KEY ix_tachograph_model_lookup (manufacturer_id, device_type, commercial_version, generation),
  CONSTRAINT fk_tachograph_model_manufacturer FOREIGN KEY (manufacturer_id) REFERENCES tachograph_manufacturer (id)
) ENGINE=InnoDB;
CREATE TABLE tachograph_identifier_type (
  id SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT, code VARCHAR(40) NOT NULL, description VARCHAR(255) NOT NULL,
  PRIMARY KEY (id), UNIQUE KEY uq_tachograph_identifier_type_code (code)
) ENGINE=InnoDB;
CREATE TABLE tachograph_identifier (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, model_id BIGINT UNSIGNED NOT NULL, manufacturer_id SMALLINT UNSIGNED NOT NULL,
  identifier_type_id SMALLINT UNSIGNED NOT NULL,
  original_identifier VARCHAR(100) NOT NULL, normalized_identifier VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id), UNIQUE KEY uq_tachograph_identifier (manufacturer_id, normalized_identifier), KEY ix_tachograph_identifier_normalized (normalized_identifier),
  CONSTRAINT fk_tachograph_identifier_model FOREIGN KEY (model_id) REFERENCES tachograph_model (id),
  CONSTRAINT fk_tachograph_identifier_manufacturer FOREIGN KEY (manufacturer_id) REFERENCES tachograph_manufacturer (id),
  CONSTRAINT fk_tachograph_identifier_type FOREIGN KEY (identifier_type_id) REFERENCES tachograph_identifier_type (id)
) ENGINE=InnoDB;
CREATE TABLE tachograph_document_occurrence (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, identifier_id BIGINT UNSIGNED NOT NULL, source_document_id SMALLINT UNSIGNED NOT NULL,
  page SMALLINT UNSIGNED NULL, vertical_position DECIMAL(10,2) NULL, observed_version VARCHAR(40) NULL,
  source_color VARCHAR(40) NULL, source_can2_status VARCHAR(50) NULL, vehicle_make VARCHAR(120) NULL,
  vehicle_type VARCHAR(255) NULL, detail TEXT NULL,
  PRIMARY KEY (id), KEY ix_tacho_occurrence_identifier (identifier_id), KEY ix_tacho_occurrence_source (source_document_id, page),
  CONSTRAINT fk_tacho_occurrence_identifier FOREIGN KEY (identifier_id) REFERENCES tachograph_identifier (id),
  CONSTRAINT fk_tacho_occurrence_source FOREIGN KEY (source_document_id) REFERENCES source_document (id)
) ENGINE=InnoDB;
CREATE TABLE tachograph_compatibility_decision (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, identifier_id BIGINT UNSIGNED NOT NULL, revision_number INT UNSIGNED NOT NULL,
  overall_result VARCHAR(40) NOT NULL, rear_can2_status VARCHAR(20) NOT NULL, front_port_status VARCHAR(20) NOT NULL,
  decision_status VARCHAR(30) NOT NULL, origin_type VARCHAR(30) NOT NULL, primary_source_document_id SMALLINT UNSIGNED NULL,
  reason TEXT NOT NULL, requires_review BOOLEAN NOT NULL DEFAULT FALSE, is_current BOOLEAN NOT NULL DEFAULT TRUE,
  supersedes_decision_id BIGINT UNSIGNED NULL, created_by BIGINT UNSIGNED NULL, reviewed_by BIGINT UNSIGNED NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id), UNIQUE KEY uq_tacho_decision_revision (identifier_id, revision_number), KEY ix_tacho_decision_current (identifier_id, is_current),
  CONSTRAINT fk_tacho_decision_identifier FOREIGN KEY (identifier_id) REFERENCES tachograph_identifier (id),
  CONSTRAINT fk_tacho_decision_source FOREIGN KEY (primary_source_document_id) REFERENCES source_document (id),
  CONSTRAINT fk_tacho_decision_previous FOREIGN KEY (supersedes_decision_id) REFERENCES tachograph_compatibility_decision (id)
) ENGINE=InnoDB;
CREATE TABLE tachograph_decision_source_document (
  decision_id BIGINT UNSIGNED NOT NULL, source_document_id SMALLINT UNSIGNED NOT NULL, evidence_role VARCHAR(20) NOT NULL,
  PRIMARY KEY (decision_id, source_document_id),
  CONSTRAINT fk_tacho_decision_source_decision FOREIGN KEY (decision_id) REFERENCES tachograph_compatibility_decision (id) ON DELETE CASCADE,
  CONSTRAINT fk_tacho_decision_source_document FOREIGN KEY (source_document_id) REFERENCES source_document (id)
) ENGINE=InnoDB;
CREATE TABLE tachograph_decision_business_rule (
  decision_id BIGINT UNSIGNED NOT NULL, business_rule_id SMALLINT UNSIGNED NOT NULL,
  PRIMARY KEY (decision_id, business_rule_id),
  CONSTRAINT fk_tacho_decision_rule_decision FOREIGN KEY (decision_id) REFERENCES tachograph_compatibility_decision (id) ON DELETE CASCADE,
  CONSTRAINT fk_tacho_decision_rule_rule FOREIGN KEY (business_rule_id) REFERENCES business_rule (id)
) ENGINE=InnoDB;

CREATE TABLE assessment_type (
  id SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT, code VARCHAR(30) NOT NULL, name VARCHAR(100) NOT NULL,
  PRIMARY KEY (id), UNIQUE KEY uq_assessment_type_code (code)
) ENGINE=InnoDB;
CREATE TABLE app_user (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, email VARCHAR(254) NOT NULL, display_name VARCHAR(160) NOT NULL,
  role_code VARCHAR(30) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id), UNIQUE KEY uq_app_user_email (email)
) ENGINE=InnoDB;
CREATE TABLE canbus_parameter (
  id SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT, code VARCHAR(60) NOT NULL, name VARCHAR(120) NOT NULL,
  description VARCHAR(255) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id), UNIQUE KEY uq_canbus_parameter_code (code)
) ENGINE=InnoDB;
CREATE TABLE canbus_document_analysis (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, document_id BIGINT UNSIGNED NOT NULL, file_asset_id BIGINT UNSIGNED NOT NULL,
  source_sha256 CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, extraction_schema_version VARCHAR(20) NOT NULL,
  status VARCHAR(30) NOT NULL, extraction_method VARCHAR(40) NOT NULL, valid_from_date DATE NULL,
  document_revision VARCHAR(30) NULL, program_number VARCHAR(40) NULL, device_model VARCHAR(120) NULL,
  internal_document_name VARCHAR(255) NULL, raw_extracted_text MEDIUMTEXT NULL, extracted_payload JSON NULL,
  confidence DECIMAL(5,4) NULL, is_current BOOLEAN NOT NULL DEFAULT TRUE,
  validated_by BIGINT UNSIGNED NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  completed_at TIMESTAMP NULL, validated_at TIMESTAMP NULL,
  PRIMARY KEY (id), UNIQUE KEY uq_canbus_analysis_cache (document_id, source_sha256, extraction_schema_version),
  KEY ix_canbus_analysis_current (document_id, is_current, status),
  CONSTRAINT fk_canbus_analysis_document FOREIGN KEY (document_id) REFERENCES canbus_document (id),
  CONSTRAINT fk_canbus_analysis_file FOREIGN KEY (file_asset_id) REFERENCES file_asset (id),
  CONSTRAINT fk_canbus_analysis_validator FOREIGN KEY (validated_by) REFERENCES app_user (id)
) ENGINE=InnoDB;
CREATE TABLE canbus_document_extraction_attempt (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, analysis_id BIGINT UNSIGNED NOT NULL, attempt_number SMALLINT UNSIGNED NOT NULL,
  method VARCHAR(40) NOT NULL, engine_name VARCHAR(100) NULL, engine_version VARCHAR(60) NULL,
  status VARCHAR(30) NOT NULL, error_message TEXT NULL, raw_response JSON NULL,
  started_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at TIMESTAMP NULL,
  PRIMARY KEY (id), UNIQUE KEY uq_canbus_extraction_attempt (analysis_id, attempt_number),
  CONSTRAINT fk_canbus_extraction_analysis FOREIGN KEY (analysis_id) REFERENCES canbus_document_analysis (id) ON DELETE CASCADE
) ENGINE=InnoDB;
CREATE TABLE canbus_document_parameter (
  analysis_id BIGINT UNSIGNED NOT NULL, parameter_id SMALLINT UNSIGNED NOT NULL,
  availability VARCHAR(20) NOT NULL, reported_unit VARCHAR(40) NULL, source_labels JSON NULL,
  confidence DECIMAL(5,4) NULL, manually_confirmed BOOLEAN NOT NULL DEFAULT FALSE,
  PRIMARY KEY (analysis_id, parameter_id), KEY ix_canbus_document_parameter_lookup (parameter_id, availability),
  CONSTRAINT fk_canbus_parameter_analysis FOREIGN KEY (analysis_id) REFERENCES canbus_document_analysis (id) ON DELETE CASCADE,
  CONSTRAINT fk_canbus_parameter_definition FOREIGN KEY (parameter_id) REFERENCES canbus_parameter (id)
) ENGINE=InnoDB;
CREATE TABLE client (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, external_code VARCHAR(60) NULL, name VARCHAR(200) NOT NULL,
  tax_identifier VARCHAR(40) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, archived_at TIMESTAMP NULL,
  PRIMARY KEY (id), UNIQUE KEY uq_client_external_code (external_code), KEY ix_client_name (name)
) ENGINE=InnoDB;
CREATE TABLE vehicle (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, client_id BIGINT UNSIGNED NOT NULL,
  registration_original VARCHAR(30) NOT NULL, registration_normalized VARCHAR(30) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  vin VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NULL, manufacturer VARCHAR(120) NULL, model VARCHAR(160) NULL,
  manufacture_year SMALLINT UNSIGNED NULL, added_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, archived_at TIMESTAMP NULL,
  PRIMARY KEY (id), UNIQUE KEY uq_vehicle_registration (registration_normalized), KEY ix_vehicle_client (client_id), KEY ix_vehicle_vin (vin),
  CONSTRAINT fk_vehicle_client FOREIGN KEY (client_id) REFERENCES client (id)
) ENGINE=InnoDB;
CREATE TABLE technical_study (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, client_id BIGINT UNSIGNED NOT NULL, study_number VARCHAR(40) NOT NULL,
  parent_study_id BIGINT UNSIGNED NULL, status VARCHAR(30) NOT NULL, title VARCHAR(200) NULL, notes TEXT NULL,
  opened_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at TIMESTAMP NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id), UNIQUE KEY uq_technical_study_number (study_number), KEY ix_study_client_date (client_id, opened_at),
  CONSTRAINT fk_study_client FOREIGN KEY (client_id) REFERENCES client (id),
  CONSTRAINT fk_study_parent FOREIGN KEY (parent_study_id) REFERENCES technical_study (id)
) ENGINE=InnoDB;
CREATE TABLE study_vehicle (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, study_id BIGINT UNSIGNED NOT NULL, vehicle_id BIGINT UNSIGNED NOT NULL,
  added_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, removed_at TIMESTAMP NULL, notes TEXT NULL,
  PRIMARY KEY (id), UNIQUE KEY uq_study_vehicle (study_id, vehicle_id),
  CONSTRAINT fk_study_vehicle_study FOREIGN KEY (study_id) REFERENCES technical_study (id),
  CONSTRAINT fk_study_vehicle_vehicle FOREIGN KEY (vehicle_id) REFERENCES vehicle (id)
) ENGINE=InnoDB;
CREATE TABLE assessment (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, study_vehicle_id BIGINT UNSIGNED NOT NULL, assessment_type_id SMALLINT UNSIGNED NOT NULL,
  status VARCHAR(30) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id), UNIQUE KEY uq_assessment_vehicle_type (study_vehicle_id, assessment_type_id),
  CONSTRAINT fk_assessment_study_vehicle FOREIGN KEY (study_vehicle_id) REFERENCES study_vehicle (id),
  CONSTRAINT fk_assessment_type FOREIGN KEY (assessment_type_id) REFERENCES assessment_type (id)
) ENGINE=InnoDB;
CREATE TABLE assessment_revision (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, assessment_id BIGINT UNSIGNED NOT NULL, revision_number INT UNSIGNED NOT NULL,
  result_code VARCHAR(50) NOT NULL, decision_status VARCHAR(30) NOT NULL, origin_type VARCHAR(30) NOT NULL,
  reason TEXT NULL, supersedes_revision_id BIGINT UNSIGNED NULL, created_by BIGINT UNSIGNED NULL, reviewed_by BIGINT UNSIGNED NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id), UNIQUE KEY uq_assessment_revision (assessment_id, revision_number), KEY ix_assessment_revision_created (assessment_id, created_at),
  CONSTRAINT fk_revision_assessment FOREIGN KEY (assessment_id) REFERENCES assessment (id),
  CONSTRAINT fk_revision_previous FOREIGN KEY (supersedes_revision_id) REFERENCES assessment_revision (id),
  CONSTRAINT fk_revision_created_by FOREIGN KEY (created_by) REFERENCES app_user (id),
  CONSTRAINT fk_revision_reviewed_by FOREIGN KEY (reviewed_by) REFERENCES app_user (id)
) ENGINE=InnoDB;
CREATE TABLE tachograph_assessment_detail (
  assessment_revision_id BIGINT UNSIGNED NOT NULL, observed_identifier_raw VARCHAR(120) NOT NULL,
  observed_identifier_normalized VARCHAR(120) NOT NULL, matched_identifier_id BIGINT UNSIGNED NULL, parsed_version VARCHAR(40) NULL,
  rear_can2_status VARCHAR(20) NOT NULL, front_port_status VARCHAR(20) NOT NULL, provisional BOOLEAN NOT NULL DEFAULT FALSE,
  requires_review BOOLEAN NOT NULL DEFAULT FALSE,
  PRIMARY KEY (assessment_revision_id),
  CONSTRAINT fk_tacho_assessment_revision FOREIGN KEY (assessment_revision_id) REFERENCES assessment_revision (id) ON DELETE CASCADE,
  CONSTRAINT fk_tacho_assessment_identifier FOREIGN KEY (matched_identifier_id) REFERENCES tachograph_identifier (id)
) ENGINE=InnoDB;
CREATE TABLE tachograph_assessment_decision (
  assessment_revision_id BIGINT UNSIGNED NOT NULL, compatibility_decision_id BIGINT UNSIGNED NOT NULL,
  PRIMARY KEY (assessment_revision_id, compatibility_decision_id),
  CONSTRAINT fk_tacho_assessment_decision_revision FOREIGN KEY (assessment_revision_id) REFERENCES assessment_revision (id) ON DELETE CASCADE,
  CONSTRAINT fk_tacho_assessment_decision_catalog FOREIGN KEY (compatibility_decision_id) REFERENCES tachograph_compatibility_decision (id)
) ENGINE=InnoDB;
CREATE TABLE canbus_assessment_detail (
  assessment_revision_id BIGINT UNSIGNED NOT NULL, manufacturer_input VARCHAR(120) NOT NULL, model_input VARCHAR(180) NOT NULL,
  manufacture_year_input SMALLINT UNSIGNED NOT NULL, vin_input VARCHAR(40) NULL, selected_document_id BIGINT UNSIGNED NULL,
  document_analysis_id BIGINT UNSIGNED NULL, document_valid_from_snapshot DATE NULL,
  result_code VARCHAR(50) NOT NULL, requires_review BOOLEAN NOT NULL DEFAULT FALSE,
  PRIMARY KEY (assessment_revision_id),
  CONSTRAINT fk_canbus_assessment_revision FOREIGN KEY (assessment_revision_id) REFERENCES assessment_revision (id) ON DELETE CASCADE,
  CONSTRAINT fk_canbus_assessment_document FOREIGN KEY (selected_document_id) REFERENCES canbus_document (id),
  CONSTRAINT fk_canbus_assessment_analysis FOREIGN KEY (document_analysis_id) REFERENCES canbus_document_analysis (id)
) ENGINE=InnoDB;
CREATE TABLE canbus_assessment_parameter (
  assessment_revision_id BIGINT UNSIGNED NOT NULL, parameter_id SMALLINT UNSIGNED NOT NULL,
  availability VARCHAR(20) NOT NULL, reported_unit VARCHAR(40) NULL, source_analysis_id BIGINT UNSIGNED NULL,
  PRIMARY KEY (assessment_revision_id, parameter_id),
  CONSTRAINT fk_canbus_assessment_parameter_revision FOREIGN KEY (assessment_revision_id) REFERENCES assessment_revision (id) ON DELETE CASCADE,
  CONSTRAINT fk_canbus_assessment_parameter_definition FOREIGN KEY (parameter_id) REFERENCES canbus_parameter (id),
  CONSTRAINT fk_canbus_assessment_parameter_analysis FOREIGN KEY (source_analysis_id) REFERENCES canbus_document_analysis (id)
) ENGINE=InnoDB;
CREATE TABLE canbus_assessment_document (
  assessment_revision_id BIGINT UNSIGNED NOT NULL, canbus_document_id BIGINT UNSIGNED NOT NULL, evidence_role VARCHAR(20) NOT NULL,
  PRIMARY KEY (assessment_revision_id, canbus_document_id),
  CONSTRAINT fk_canbus_evidence_revision FOREIGN KEY (assessment_revision_id) REFERENCES assessment_revision (id) ON DELETE CASCADE,
  CONSTRAINT fk_canbus_evidence_document FOREIGN KEY (canbus_document_id) REFERENCES canbus_document (id)
) ENGINE=InnoDB;
CREATE TABLE assessment_revision_source_document (
  assessment_revision_id BIGINT UNSIGNED NOT NULL, source_document_id SMALLINT UNSIGNED NOT NULL,
  source_locator VARCHAR(255) NULL, evidence_role VARCHAR(20) NOT NULL,
  PRIMARY KEY (assessment_revision_id, source_document_id),
  CONSTRAINT fk_revision_source_revision FOREIGN KEY (assessment_revision_id) REFERENCES assessment_revision (id) ON DELETE CASCADE,
  CONSTRAINT fk_revision_source_document FOREIGN KEY (source_document_id) REFERENCES source_document (id)
) ENGINE=InnoDB;
CREATE TABLE assessment_revision_business_rule (
  assessment_revision_id BIGINT UNSIGNED NOT NULL, business_rule_id SMALLINT UNSIGNED NOT NULL,
  PRIMARY KEY (assessment_revision_id, business_rule_id),
  CONSTRAINT fk_revision_rule_revision FOREIGN KEY (assessment_revision_id) REFERENCES assessment_revision (id) ON DELETE CASCADE,
  CONSTRAINT fk_revision_rule_rule FOREIGN KEY (business_rule_id) REFERENCES business_rule (id)
) ENGINE=InnoDB;
CREATE TABLE attachment_link (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, file_asset_id BIGINT UNSIGNED NOT NULL, client_id BIGINT UNSIGNED NULL,
  vehicle_id BIGINT UNSIGNED NULL, study_id BIGINT UNSIGNED NULL, assessment_id BIGINT UNSIGNED NULL,
  attachment_type VARCHAR(40) NOT NULL, uploaded_by BIGINT UNSIGNED NULL, uploaded_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id), KEY ix_attachment_client (client_id), KEY ix_attachment_vehicle (vehicle_id), KEY ix_attachment_study (study_id),
  CONSTRAINT fk_attachment_file FOREIGN KEY (file_asset_id) REFERENCES file_asset (id),
  CONSTRAINT fk_attachment_client FOREIGN KEY (client_id) REFERENCES client (id),
  CONSTRAINT fk_attachment_vehicle FOREIGN KEY (vehicle_id) REFERENCES vehicle (id),
  CONSTRAINT fk_attachment_study FOREIGN KEY (study_id) REFERENCES technical_study (id),
  CONSTRAINT fk_attachment_assessment FOREIGN KEY (assessment_id) REFERENCES assessment (id),
  CONSTRAINT fk_attachment_user FOREIGN KEY (uploaded_by) REFERENCES app_user (id),
  CONSTRAINT ck_attachment_has_target CHECK (client_id IS NOT NULL OR vehicle_id IS NOT NULL OR study_id IS NOT NULL OR assessment_id IS NOT NULL)
) ENGINE=InnoDB;
CREATE TABLE study_event (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, study_id BIGINT UNSIGNED NOT NULL, vehicle_id BIGINT UNSIGNED NULL,
  event_type VARCHAR(40) NOT NULL, detail TEXT NULL, performed_by BIGINT UNSIGNED NULL, occurred_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id), KEY ix_study_event_timeline (study_id, occurred_at),
  CONSTRAINT fk_study_event_study FOREIGN KEY (study_id) REFERENCES technical_study (id),
  CONSTRAINT fk_study_event_vehicle FOREIGN KEY (vehicle_id) REFERENCES vehicle (id),
  CONSTRAINT fk_study_event_user FOREIGN KEY (performed_by) REFERENCES app_user (id)
) ENGINE=InnoDB;
CREATE TABLE audit_event (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, entity_type VARCHAR(50) NOT NULL, entity_id BIGINT UNSIGNED NOT NULL,
  action VARCHAR(30) NOT NULL, actor_id BIGINT UNSIGNED NULL, before_data JSON NULL, after_data JSON NULL,
  occurred_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id), KEY ix_audit_entity (entity_type, entity_id, occurred_at),
  CONSTRAINT fk_audit_actor FOREIGN KEY (actor_id) REFERENCES app_user (id)
) ENGINE=InnoDB;


START TRANSACTION;










































