INSERT INTO source_document (id, file_asset_id, code, domain, source_type, title, document_date, notes) VALUES
  (1, 1, 'VDO_2019', 'TACHOGRAPH', 'MANUFACTURER_DOCUMENT', 'VDO Tacho Versions 2019 - DTCO Uebersicht 3.0', '2018-08-02', 'Fuente principal de colores de compatibilidad CAN2.'),
  (2, 2, 'VDO_2023', 'TACHOGRAPH', 'MANUFACTURER_DOCUMENT', 'DTCO-KITAS-DSRC-4.1 Overview 2023-05-31', '2023-05-31', 'Fuente de identificacion de modelos; no declara directamente la compatibilidad CAN2.'),
  (3, NULL, 'REQUISITOS_PROYECTO', 'TACHOGRAPH', 'INTERNAL_REQUIREMENT', 'Requisitos iniciales del proyecto', NULL, 'Ejemplos y criterios indicados por el propietario del proyecto.');
INSERT INTO business_rule (id, code, version, domain, description) VALUES
  (1, 'VDO_2019_GREEN_CAN2', '1.0.0', 'TACHOGRAPH', 'Un modelo VDO marcado en verde en el documento de 2019 admite CAN2 trasera.'),
  (2, 'VDO_2019_ORANGE_FRONT_ONLY', '1.0.0', 'TACHOGRAPH', 'Un modelo VDO marcado en naranja se clasifica como compatible solo por el puerto frontal.'),
  (3, 'VDO_2019_RED_NOT_COMPATIBLE', '1.0.0', 'TACHOGRAPH', 'Un modelo VDO marcado en rojo se clasifica como no compatible.'),
  (4, 'VDO_2023_ONLY_CAN2', '1.0.0', 'TACHOGRAPH', 'Un modelo presente únicamente en el documento VDO de 2023 se infiere compatible con CAN2 trasera.'),
  (5, 'VDO_NON_1381_ANALOG', '1.0.0', 'TACHOGRAPH', 'En VDO, un identificador que no comienza por 1381 se considera analógico.'),
  (6, 'STONERIDGE_GT_7_CAN2', '1.0.0', 'TACHOGRAPH', 'Una versión Stoneridge superior a 7.0 se considera compatible con CAN2 trasera.'),
  (7, 'STONERIDGE_LTE_7_NO_CAN2', '1.0.0', 'TACHOGRAPH', 'Una versión Stoneridge igual o inferior a 7.0 se considera no compatible con CAN2.'),
  (8, 'STONERIDGE_FRONT_UNSUPPORTED', '1.0.0', 'TACHOGRAPH', 'Stoneridge no ofrece descarga remota mediante conexión frontal.'),
  (9, 'EXPLICIT_REQUIREMENT_OVERRIDE', '1.0.0', 'TACHOGRAPH', 'Una excepción declarada expresamente prevalece y queda pendiente de revisión si contradice documentación.'),
  (10, 'CANBUS_YEAR_INTERVAL', '1.0.0', 'CANBUS', 'Para un año intermedio se selecciona el esquema de inicio más reciente que no exceda el año del vehículo.'),
  (11, 'CANBUS_BEFORE_FIRST_UNSUPPORTED', '1.0.0', 'CANBUS', 'Un vehículo anterior al primer esquema disponible no queda cubierto.'),
  (12, 'CANBUS_AFTER_LAST_REVIEW', '1.0.0', 'CANBUS', 'Un vehículo posterior al último esquema requiere revisión si la vigencia interna no permite confirmarlo.'),
  (13, 'CANBUS_SAME_YEAR_REVIEW', '1.0.0', 'CANBUS', 'La coincidencia exacta con el año de ficha técnica puede requerir revisión por incertidumbre sobre la fecha real de fabricación.'),
  (14, 'CANBUS_QUALIFIER_MATCH', '1.0.0', 'CANBUS', 'Los calificadores del nombre, incluidos prefijo VIN, propulsión, variante y mercado, deben coincidir cuando existan.');
INSERT INTO assessment_type (id, code, name) VALUES
